import{_ as a,o as n,c as r,j as e,a as o}from"./chunks/framework.Bd7kzaCy.js";const f=JSON.parse('{"title":"D.26　网络、媒体、语言、叙事与认同","description":"","frontmatter":{"title":"D.26　网络、媒体、语言、叙事与认同"},"headers":[],"relativePath":"theory/appendix-d/d-26.md","filePath":"theory/appendix-d/d-26.md"}'),l={name:"theory/appendix-d/d-26.md"};function d(s,t,p,i,c,u){return n(),r("div",null,[...t[0]||(t[0]=[e("div",{class:"theory-source"},[e("h1",{id:"section-d-26",tabindex:"-1"},[o("D.26　网络、媒体、语言、叙事与认同 "),e("a",{class:"header-anchor",href:"#section-d-26","aria-label":'Permalink to "D.26　网络、媒体、语言、叙事与认同 {#section-d-26}"'},"​")]),e("p",null,"正文连接：§5.5.3、5.10；§9.7；§10—11；§15.3.4、15.3.6。研究入口：26.01—26.12。"),e("p",null,"网络可以带来机会，语言可以使经验被理解，叙事可以帮助哀悼和责任讨论，身份可以支持合作。分析应保留这些正面作用，同时区分连接、实际帮助、曝光、阅读、信念、公开表达和行动。弱联系、桥位、结构洞、中心性与真实可动员资源不是同义词。"),e("p",null,"教学例：两组三人各自互连，组间只有一条边。若收到一个已行动邻居提示就采取行动，传播可能跨过去；若需要两个不同邻居共同支持，消息到达也未必足够。重复独立尝试的累计成功率1−(1−p)^n，不等于社会强化。多个社会节点可以提供支持，却仍共用同一事实来源。"),e("p",null,"沉默可能来自风险、隐私、未接触或无兴趣，不能自动推成赞成或反对。未核实、已证明错误和蓄意欺骗是不同状态；强烈群体情绪不必不理性，真实危害也不能让一个身份群体承担全部责任。清楚边界不等封闭，认同融合或高代价行为不自动证明自由同意。"),e("p",null,"翻译要分词句、整段消息、受众任务和代表权限；语言能力、听者理解、制度准入与内容质量各有通道。叙事细读可以解释经验和意义，却不替代技术因果；反过来，技术原因明确也不使记忆与文学任务多余。后来取得的事实不能回填为当日讲述者已经知道的内容。"),e("p",null,"平台处理需保留实际版本：改变信息流、某项排序权重、内容匹配或作者反馈，不能共用一个处理标签。固定推荐规则也可以经人的响应形成反馈，模型重训不是所有反馈的必要条件。系统画像变化、私人偏好、实际机会和长期伤害分别评价；原始事实来源重复不取消多位支持者可能产生的社会协调。"),e("p",null,"专题定位：26.01 弱连接、结构洞与网络资源：Granovetter、Burt；26.02 扩散、阈值与复杂传播：Granovetter、Watts、Centola；26.03 社会认同、自我分类与群体边界：Tajfel、John Turner；26.04 议程设置、框架与媒介选择；26.05 沉默、螺旋、谣言与错误信息；26.06 叙事、记忆、隐喻与公共解释；26.07 平台注意力、推荐与舆情；26.08 跨语言翻译与概念迁移；26.09 语言学习、语言制度与表达不平等；26.10 不确定性—认同与最优差异性；26.11 群体情绪、恐惧管理与道德恐慌；26.12 认同融合与高代价共同经历。")],-1)])])}const m=a(l,[["render",d]]);export{f as __pageData,m as default};
